"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[6988],{2056(e){e.exports=JSON.parse('{"title":"\uc6b0\ub9ac\uac00 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uadfc\uac04\uc744 \ubc30\uc6cc\uc57c \ud558\ub294 \uc774\uc720","date":"2026-06-04","coverUrl":"/kudzu-based-bench/assets/notion/17a793b57dedee05.png","html":"<h1 data-notion-block-id=\\"36be548d-8a8e-8098-b876-e3e74c957f12\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"36be548d-8a8e-802d-9a96-eccee1f64f74\\" id=\\"36be548d-8a8e-802d-9a96-eccee1f64f74\\">\uc6b0\ub9ac\uac00 \ud504\ub808\uc784\uc6cc\ud06c\uc758 \uadfc\uac04\uc744 \ubc30\uc6cc\uc57c \ud558\ub294 \uc774\uc720</h2><a href=\\"https://saschb2b.com/ko/blog/flight-protocol-dos\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://saschb2b.com/ko/blog/flight-protocol-dos</a><p data-notion-block-id=\\"370e548d-8a8e-80f9-93b1-da33c381fa93\\">React Server Components \uad00\ub828 \ucde8\uc57d\uc810 \uc911\uc5d0\uc11c Flight \ud504\ub85c\ud1a0\ucf5c\uc774 \uc65c \ubb38\uc81c\uac00 \ub418\uc5c8\ub294\uc9c0 Flight \ud504\ub85c\ud1a0\ucf5c\uc774 \ubb34\uc5c7\uc778\uc9c0\ub97c \ubc14\ud0d5\uc73c\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc774\uc790, \ud504\ub808\uc784\uc6cc\ud06c\uc5d0\uc11c \ubb38\uc11c\ub97c \uc81c\uacf5\ud558\ub294, \uadf8\ub9ac\uace0 \uc8fc\ub85c \ubcf4\uc5ec\uc8fc\ub294 API\ub9cc \uc544\ub294 \uac83\ub9cc\uc774 \ub05d\uc774 \uc544\ub2d8\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uac00\uc7a5 \ucc98\uc74c \ubc1c\uacac\ub41c RSC\uad00\ub828 \ucde8\uc57d\uc810\uc778 React2Shell(<a href=\\"https://lachlan.nz/blog/the-react2shell-story/\\">React2Shell \ubc1c\uacac\uae30</a>, <a href=\\"https://sylvie.fyi/posts/react2shell/\\">2</a>)\ub610\ud55c Flight \ud504\ub85c\ud1a0\ucf5c \uae30\ubc18 \ucde8\uc57d\uc810\uc774\ubbc0\ub85c, \uc774 \uae00\uc758 \ub9c8\uc9c0\ub9c9\uc778 tRPC/GraphQL/Websocket\uc758 \uacbd\uacc4\uc5d0\ub3c4 \uc801\uc6a9\ub418\ubbc0\ub85c \ud504\ub808\uc784\uc6cc\ud06c/\ud504\ub85c\ud1a0\ucf5c \ub610\ud55c \uc6b0\ub9ac\uac00 \uc54c\uc544\uc57c \ud568\uc744 \uac04\uc811\uc801\uc73c\ub85c \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-8063-959a-fbf00e2807c6\\" id=\\"36be548d-8a8e-8063-959a-fbf00e2807c6\\">AI\uc5d0 \ub300\ud55c \uc2dc\ub2c8\uc5b4 \uac1c\ubc1c\uc790\uc758 \uc0dd\uac01</h2><a href=\\"https://blog.isquaredsoftware.com/2026/05/ai-thoughts-part-1-fears-opinions-journey/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.isquaredsoftware.com/2026/05/ai-thoughts-part-1-fears-opinions-journey/</a><p data-notion-block-id=\\"36ee548d-8a8e-8002-90c3-fdaf3ef144a8\\">Redux \uba54\uc778\ud14c\uc774\ub108 \ub9c8\ud06c \uc5d0\ub9ad\uc2a8\uc774 \uc4f4 12,000\uc790\uc9dc\ub9ac \uae00\uc785\ub2c8\ub2e4. 25\ub144\ucc28 \uac1c\ubc1c\uc790\uac00 AI \uc55e\uc5d0\uc11c \uc790\uae30\ub3c4 \ud55c\ub3d9\uc548 \ubb34\ub108\uc84c\uc5c8\ub2e4\uace0 \uace0\ubc31\ud558\ub294 \uae00\ub85c, \uac70\ubd80\ud558\ub2e4\uac00, \uac00\ubcbc\uc6b4 \uc6b0\uc6b8\uc758 \uc2dc\uae30\ub97c \uc9c0\ub098\uace0, \ub9c8\uc9c0\ubabb\ud574 \ubc1b\uc544\ub4e4\uc774\uace0, \uadf8\ub7f0\ub370\ub3c4 \\"\ub0b4 \ub450\ub824\uc6c0 \ub300\ubd80\ubd84\uc740 \uc9c0\uae08\ub3c4 \uc5ec\uc804\ud788 \uc720\ud6a8\ud558\ub2e4\\"\uace0 \ub05d\ub0b4 \ubabb \ubc15\uc2b5\ub2c8\ub2e4. \uc815\ubcf4 \uc804\ub2ec\uc774 \uacf5\uc9dc\uac00 \ub41c \uc2dc\ub300\uc5d0, \uc815\ubcf4\ub97c \uc8fc\ub824\ub294 \uae00\uc740 AI\uc640 \uac19\uc740 \ud2b8\ub799\uc5d0\uc11c \uacbd\uc7c1\ud558\ub2e4 \uc9d1\ub2c8\ub2e4. \uc88b\uc740 \uae00\uc774 \uc8fc\ub358 \uac00\uce58\ub294 \uc6d0\ub798 \uadf8 \uc606\uc5d0 \ubd99\uc740 \uac83\ub4e4, \ud310\ub2e8\uacfc \uc99d\uc5b8\uacfc \ubc29\ud5a5\uc774\uc5c8\uace0, \uc774\uac74 AI\ud55c\ud14c \ubb3c\uc5b4\ubcfc \uc218 \uc5c6\ub294 \uac83\ub4e4\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-802b-8e2e-d5f3af366a42\\" id=\\"36be548d-8a8e-802b-8e2e-d5f3af366a42\\">jotai\ub97c \uc815\ud655\ud558\uac8c \uc0ac\uc6a9\ud558\ub294 \ubc29\ubc95</h2><a href=\\"https://www.peterp.me/articles/jotai-structural-sharing-vs-selectatom/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.peterp.me/articles/jotai-structural-sharing-vs-selectatom/</a><p data-notion-block-id=\\"370e548d-8a8e-80bf-909e-e1024683e7d1\\">jotai\uc758 \ud30c\uc0dd atom\uc774 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b8\uc81c \ubb38\uc81c\uac00 \ub418\ub294\uc9c0 \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. <code>Object.is</code>\ub294 <code>React.memo</code>\uc5d0\ub3c4 \uc4f0\uc774\ubbc0\ub85c(<a href=\\"https://ones-to-watch.ethansup.net/news/post/8b8e4348-60f9-477e-9892-e7dfdf611fe0#b0fa8093-7010-49bd-9e12-b95e81fcacef\\">React.memo\ub97c \ub354 \ube60\ub974\uac8c</a>), \ud30c\uc0dd \uac12\uc744 \uc0dd\uc131\ud560 \ub54c \uc5b4\ub290 \ubc29\uc2dd\uc774 \uc88b\uc740\uc9c0 \ud55c \ubc88 \ub354 \uc0dd\uac01\ud558\uac8c \ub9cc\ub4dc\ub294 \uae00\uc774\ubbc0\ub85c, jotai\ub97c \uc0ac\uc6a9\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \ud30c\uc0dd \uac12\uc744 \ub9ce\uc774 \uc0ac\uc6a9\ud55c\ub2e4\uba74 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-800b-8d91-d4b09d3e50e1\\" id=\\"36be548d-8a8e-800b-8d91-d4b09d3e50e1\\">\ube60\ub978 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc740 \ucd5c\uc2e0 \ub370\uc774\ud130\ub97c \ubcf4\uc5ec\uc8fc\uc9c0 \uc54a\ub294\ub2e4.</h2><a href=\\"https://github.blog/engineering/architecture-optimization/from-latency-to-instant-modernizing-github-issues-navigation-performance/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.blog/engineering/architecture-optimization/from-latency-to-instant-modernizing-github-issues-navigation-performance/</a><a href=\\"https://performance.dev/how-is-linear-so-fast-a-technical-breakdown\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://performance.dev/how-is-linear-so-fast-a-technical-breakdown</a><p data-notion-block-id=\\"36be548d-8a8e-8069-8297-dd786181f127\\">\uccab\ubc88\uc9f8 \uae00\uc740 GitHub Issues \ud300\uc774 Rails/React\uac00 \uc11e\uc778 \uae30\uc874 \uad6c\uc870\ub97c \ud1b5\uc9f8\ub85c \ub2e4\uc2dc \uc9dc\uc9c0 \uc54a\uace0, IndexedDB \ud074\ub77c\uc774\uc5b8\ud2b8 \uce90\uc2dc\uc640 stale-while-revalidate, service worker\ub9cc\uc73c\ub85c \ud398\uc774\uc9c0 \uc774\ub3d9\uc744 \uc989\uac01\uc801\uc73c\ub85c \ub290\ub07c\uac8c \ub9cc\ub4e0 \uacfc\uc815\uc744 \ub2e8\uacc4\ubcc4\ub85c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub450\ubc88\uc9f8 \uae00\uc740 Linear\uc758 \uc18d\ub3c4\uac00 \uc5b4\ub514\uc11c \ub098\uc624\ub294\uc9c0 \uc804\ubc18\uc744 \ub72f\uc5b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc11c\ubc84\ub97c \uc815\ub2f5\uc758 \ucd9c\ucc98\uac00 \uc544\ub2c8\ub77c \ub3d9\uae30\ud654 \ub300\uc0c1\uc73c\ub85c \ub450\uace0 \ubaa8\ub4e0 \uac83\uc744 \ub85c\uceec\uc5d0\uc11c \uba3c\uc800 \ucc98\ub9ac\ud55c\ub2e4\ub294 \ud55c \ubc88\uc758 \uacb0\uc815\uc774, \uc5b4\ub5bb\uac8c CSR \uc571\uc744 SSR\ubcf4\ub2e4 \ube60\ub974\uac8c \ub290\uaef4\uc9c0\uac8c \ub9cc\ub4dc\ub294\uc9c0 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4. sync engine \uc790\uccb4\uac00 \uad81\uae08\ud558\uc2dc\ub2e4\uba74 <a href=\\"https://ones-to-watch.ethansup.net/news/post/1bfe548d-8a8e-80b8-af8c-e6d92b1df9fd#1bfe548d-8a8e-80ae-a311-da196b44a7ee\\">Sync Engine\uc774 \uadf8\ub9ac\ub294 \ubbf8\ub798</a>\ub97c, \ub9c8\uc9c0\ub9c9 \uc560\ub2c8\uba54\uc774\uc158 \ud30c\ud2b8\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/262e548d-8a8e-80eb-9e8b-cd0868f2c950#279e548d-8a8e-8022-9f2e-d1f4b2ef40ab\\">\uc560\ub2c8\uba54\uc774\uc158\uc740 \ud56d\uc0c1 \ud544\uc694\ud558\uc9c0 \uc54a\ub2e4</a>\uc640 \ud568\uaed8 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ub450 \uae00 \ubaa8\ub450 \ub300\uc6a9\ub7c9 \ub370\uc774\ud130\ub97c \uc5b4\ub5bb\uac8c \ube60\ub974\uac8c \ubcf4\uc5ec\uc904 \uc218 \uc788\uc5c8\ub294\uc9c0 \uc811\uadfc \ubc29\uc2dd\uc744 \ub2e4\ub974\uac8c \ubcf4\uc5ec\uc8fc\ubbc0\ub85c, \uc0c1\ud669\uc5d0 \ub9de\uac8c \uc0ac\uc6a9\ud558\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"36be548d-8a8e-80b8-a77f-e4021aeb34c7\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"370e548d-8a8e-8049-a793-d0e22e222be2\\" id=\\"370e548d-8a8e-8049-a793-d0e22e222be2\\">Router\uc5d0\ub3c4 \uce90\uc2dc\uac00 \uc788\ub294\ub370 \uc65c Query\ub97c \uc4f0\ub294\uac00</h2><a href=\\"https://tkdodo.eu/blog/tan-stack-router-and-query\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tkdodo.eu/blog/tan-stack-router-and-query</a><p data-notion-block-id=\\"375e548d-8a8e-801d-bc2e-ee6365e48405\\">Router \uce90\uc2dc\ub294 route\ubcc4\ub85c \uac07\ud600 \uc788\uace0 Query \uce90\uc2dc\ub294 \uc804\uc5ed\uc774\ub77c\ub294 \ucc28\uc774\uc5d0\uc11c \ucd9c\ubc1c\ud574\uc11c \uac01\uac01\uc758 fetching \ub3c4\uad6c\ub97c \uc5b4\ub5bb\uac8c \uc368\uc57c \ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"370e548d-8a8e-806f-a019-c7a0542b9105\\" id=\\"370e548d-8a8e-806f-a019-c7a0542b9105\\">\ubaa8\ub358 \uc6f9 \uac00\uc774\ub4dc Skill</h2><a href=\\"https://developer.chrome.com/docs/modern-web-guidance?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/docs/modern-web-guidance?hl=ko</a><p data-notion-block-id=\\"370e548d-8a8e-8040-9254-eae8cea01030\\">Chrome \uac1c\ubc1c\uc790 \ubb38\uc11c\uc5d0 \ucd94\uac00\ub41c \ucd5c\uc2e0 \uc6f9 \ubaa8\ubc94 \uc0ac\ub840\xb7Baseline \uae30\ubc18 \uac00\uc774\ub4dc \uc139\uc158\uc785\ub2c8\ub2e4. \ub808\ud37c\ub7f0\uc2a4\ub85c \uac00\ubccd\uac8c \uc0b4\ud3b4\ubcfc \ub9cc\ud569\ub2c8\ub2e4. \ubb3c\ub860 \uc811\uadfc\uc131 \uce21\uba74\uacfc \uc81c\ub300\ub85c \uc801\uc6a9\ub418\ub294\uc9c0\uc5d0 \ub300\ud574\uc11c\ub294 <a href=\\"https://adrianroselli.com/2026/05/maybe-dont-rely-on-googles-modern-web-guidance.html\\">\ubd80\uc871\ud55c \uba74\uc774 \uc5c6\uc796\uc544 \uc788\ub294 \uac83\uc740 \uba85\uc2ec\ud558\uc138\uc694</a>.</p><h2 data-notion-block-id=\\"370e548d-8a8e-8077-b4f8-da0952f9349d\\" id=\\"370e548d-8a8e-8077-b4f8-da0952f9349d\\">JS \uc560\ub2c8\uba54\uc774\uc158\uacfc CSS\uc758 \uc9c4\uc9dc \ucc28\uc774</h2><a href=\\"https://www.joshwcomeau.com/animation/css-vs-javascript/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/animation/css-vs-javascript/</a><p data-notion-block-id=\\"375e548d-8a8e-80a7-9b20-ec4c96255396\\">\ud754\ud788 JS\uac00 CSS\ubcf4\ub2e4 \ub290\ub9ac\ub2e4\uace0 \ud558\uc9c0\ub9cc, \uc2e4\uc81c \ubcc0\uc218\ub294 \uc5b8\uc5b4\uac00 \uc544\ub2c8\ub77c \uc5b4\ub290 \uc2a4\ub808\ub4dc\uc5d0\uc11c \uc2e4\ud589\ub418\ub290\ub0d0\uc785\ub2c8\ub2e4. \uadf8 \ubc14\ud0d5\uc73c\ub85c CSS \uc560\ub2c8\uba54\uc774\uc158\uacfc JS \uc560\ub2c8\uba54\uc774\uc158 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 \uc5b4\ub5a4 \uc7a5\ub2e8\uc810\uc744 \uac00\uc9c0\uace0 \uc788\ub294\uc9c0, \uadf8\ub9ac\uace0 \uc5b4\ub5a8\ub54c \uc5b4\ub5a4 \ubc29\uc2dd\uc744 \ud0dd\ud558\ub294\uc9c0 \uc88b\uc740\uc9c0 \uc124\uba85\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"36be548d-8a8e-808d-89a3-f715de178d85\\" id=\\"36be548d-8a8e-808d-89a3-f715de178d85\\">round()\ub85c \ub354 \uc608\uce21 \uac00\ub2a5\ud55c Fluid Typography</h2><a href=\\"https://ishadeed.com/article/css-round/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/css-round/</a><p data-notion-block-id=\\"36be548d-8a8e-8053-9840-ebeec7c4b5aa\\"><code>clamp()</code>\uc640 \ucee8\ud14c\uc774\ub108 \ub2e8\uc704\ub85c \ub9cc\ub4e0 \uac12\uc774 19.7px \uac19\uc740 \uc5b4\uc911\uac04\ud55c \uc218\ub85c \ub5a8\uc5b4\uc9c0\ub294 \ubb38\uc81c\ub97c, CSS <code>round()</code>\ub97c \ud1b5\ud574 \ud574\uacb0\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"370e548d-8a8e-8068-a92a-cfe7787df046\\" id=\\"370e548d-8a8e-8068-a92a-cfe7787df046\\">\ud0a4\ubcf4\ub4dc \ucee8\ud2b8\ub864 for React Native</h2><a href=\\"https://blog.margelo.com/deep-dive-in-keyboard-handling\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.margelo.com/deep-dive-in-keyboard-handling</a><h2 data-notion-block-id=\\"370e548d-8a8e-8010-a9e4-df3433e4dbed\\" id=\\"370e548d-8a8e-8010-a9e4-df3433e4dbed\\">\uac00\uc6b4\ub370 \uc815\ub82c 2026\ub144 \ubc84\uc804</h2><a href=\\"https://css-tricks.com/the-state-of-css-centering-in-2026/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://css-tricks.com/the-state-of-css-centering-in-2026/</a><h2 data-notion-block-id=\\"370e548d-8a8e-80dd-a183-ef5b1c933a5a\\" id=\\"370e548d-8a8e-80dd-a183-ef5b1c933a5a\\">RTL\uc744 \uc704\ud55c 2\uac00\uc9c0 \uc218\uc815\uc548</h2><a href=\\"https://evilmartians.com/chronicles/600-million-people-write-right-to-left-2-fixes-your-app-needs\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://evilmartians.com/chronicles/600-million-people-write-right-to-left-2-fixes-your-app-needs</a><h2 data-notion-block-id=\\"370e548d-8a8e-8006-936f-dce953cc2db0\\" id=\\"370e548d-8a8e-8006-936f-dce953cc2db0\\">RSC \uae30\ubc18 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \uc811\uadfc\ubc95</h2><a href=\\"https://aurorascharff.no/posts/component-architecture-for-react-server-components/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://aurorascharff.no/posts/component-architecture-for-react-server-components/</a><h1 data-notion-block-id=\\"36be548d-8a8e-80c3-8c75-cc06c31e0837\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://docs.npmjs.com/staged-publishing\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://docs.npmjs.com/staged-publishing</a><p data-notion-block-id=\\"36be548d-8a8e-80c1-8a3b-f0b562010666\\">\ubc1c\ud589\uc744 staged \ub2e8\uacc4\ub85c \uac70\ub294 npm \uacf5\uc2dd \uae30\ub2a5 \ubb38\uc11c\uc785\ub2c8\ub2e4. \ucd5c\uadfc \uc787\ub530\ub978 \uacf5\uae09\ub9dd \uc0ac\uace0 \ud750\ub984\uacfc \ub9de\ubb3c\ub824, \ubc30\ud3ec \ud30c\uc774\ud504\ub77c\uc778\uc744 \uacac\uace0\ud558\uac8c \ub9cc\ub4dc\ub294 \ubc29\ubc95\uc73c\ub85c \uc0b4\ud3b4\ubcfc \ub9cc\ud569\ub2c8\ub2e4.</p><a href=\\"https://www.microsoft.com/en-us/security/blog/2026/05/20/mini-shai-hulud-compromised-antv-npm-packages-enable-ci-cd-credential-theft/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.microsoft.com/en-us/security/blog/2026/05/20/mini-shai-hulud-compromised-antv-npm-packages-enable-ci-cd-credential-theft/</a><p data-notion-block-id=\\"36be548d-8a8e-807a-a501-fc1eebed9439\\">5\uc6d4 19\uc77c npm \uacc4\uc815 \ud558\ub098\uac00 \ud0c8\ucde8\ub418\uc5b4 22\ubd84 \ub9cc\uc5d0 317\uac1c \ud328\ud0a4\uc9c0\uc5d0 637\uac1c \uc545\uc131 \ubc84\uc804\uc774 \uc790\ub3d9\uc73c\ub85c \uc3df\uc544\uc9c4 \uc0ac\uace0 \ubd84\uc11d\uc785\ub2c8\ub2e4. <code>echarts-for-react</code>\xb7<code>timeago.js</code>\xb7\ub2e4\uc218\uc758 <code>@antv</code> \uc2a4\ucf54\ud504 \ud328\ud0a4\uc9c0 \ub4f1 \uc6d4 1,500\ub9cc+ \ub2e4\uc6b4\ub85c\ub4dc \uaddc\ubaa8\uac00 \uc601\ud5a5\ubc1b\uc558\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://www.jasnell.me/posts/quic-comes-to-node\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.jasnell.me/posts/quic-comes-to-node</a><p data-notion-block-id=\\"36be548d-8a8e-803a-8e5d-d46e888c624c\\">\uc218\ub144\uc758 \uc791\uc5c5 \ub05d\uc5d0 <code>node:quic</code> \ubaa8\ub4c8\uc774 <code>--experimental-quic</code> \ud50c\ub798\uadf8 \ub4a4\uc5d0 \ub4e4\uc5b4\uc654\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4(\uc2dc\ub9ac\uc988 1\ud3b8). ngtcp2/nghttp3/OpenSSL/libuv \uc704\uc5d0 <code>QuicEndpoint</code>\xb7<code>QuicSession</code>\xb7<code>QuicStream</code>\xb7<code>QuicError</code>\ub97c \ub178\ucd9c\ud558\uba70, head-of-line blocking \uc5c6\ub294 \uba40\ud2f0\ud50c\ub809\uc2f1, \ube60\ub978 \ud578\ub4dc\uc170\uc774\ud06c, \uc5f0\uacb0 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uac19\uc740 QUIC \ud2b9\uc131\uc744 \ub124\uc774\ud2f0\ube0c\ub85c \uac00\uc838\uc635\ub2c8\ub2e4.</p><a href=\\"https://tanstack.com/start/latest/docs/framework/react/guide/deferred-hydration\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tanstack.com/start/latest/docs/framework/react/guide/deferred-hydration</a><p data-notion-block-id=\\"36be548d-8a8e-8016-9a20-fc5af6bb2ae1\\">TanStack Start\uc758 \uc2e4\ud5d8\uc801 \uae30\ub2a5 \ubb38\uc11c\ub85c, \ucd08\uae30 \ub85c\ub4dc \uc2dc \uc11c\ubc84\uac00 \uc720\uc6a9\ud55c HTML\uc744 \ube68\ub9ac \ubcf4\uc5ec\uc8fc\uace0 \uadf8\uac83\uc744 \uc778\ud130\ub799\ud2f0\ube0c\ud558\uac8c \ub9cc\ub4dc\ub294 \ud074\ub77c\uc774\uc5b8\ud2b8 \uce21 \ud558\uc774\ub4dc\ub808\uc774\uc158 \uc791\uc5c5\uc744 \uc9c0\uc5f0(defer)\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.</p><a href=\\"https://developer.chrome.com/blog/declarative-partial-updates?hl=ko\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.chrome.com/blog/declarative-partial-updates?hl=ko</a><p data-notion-block-id=\\"36be548d-8a8e-8054-96af-f97e50c6931b\\">HTML\uc774 \uc704\uc5d0\uc11c \uc544\ub798\ub85c \uc21c\uc11c\ub300\ub85c \uc804\ub2ec\ub41c\ub2e4\ub294 \ubcf8\uc9c8\uc801 \uc81c\uc57d\uc744 \uc904\uc774\ub824\ub294 Chrome\uc758 \uc0c8 \ud50c\ub7ab\ud3fc \uc791\uc5c5\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p>"}')}}]);